import{d as c,C as t,o as u,c as b,j as a,a as n,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十五章","description":"依巧诈与守真辨明民、愚之，读智术治国的反效与返真大顺。","frontmatter":{"title":"道德经第六十五章","description":"依巧诈与守真辨明民、愚之，读智术治国的反效与返真大顺。","category":"guide","aliases":["道德经第六十五章","老子第六十五章","dao de jing chapter 65"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-65.md","filePath":"daoism/dao-de-jing/chapter-65.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-65.md"},y=c({...p,setup(g){const i=[{id:"illumination-and-plainness",label:"非以明民，将以愚之",showLabel:!0,sentences:[["古之善为道者，非以",{text:"明",glossary:"ming"},"民，将以",{text:"愚",glossary:"yu"},"之。"]],note:["【白话】按本章王注：古来善于行道的治理者，不以使民竞逐巧诈为取向，而要使他们归于愚朴、守真顺自然。明民与愚之在这里构成治理方向的对照。","【王弼注择要】「明，谓多见巧诈，蔽其朴也。」愚下注「愚，谓无知守真，顺自然也」，分别给出本章的特定含义。","【读法】明在此不是第三十三章自知之明，愚也不只按愚笨直译。经注仍由在上者安排民的状态，不能省略这层古代立场，只留下今天容易接受的自我修养说法。"]},{id:"cunning-and-the-difficulty-of-government",label:"民之难治，以其智多",showLabel:!0,sentences:[["民之难治，以其",{text:"智",glossary:"zhi"},"多。"]],note:["【白话】百姓难以治理，章内归因于机巧诈术增多。依下文王注，这也与治理者先用智术挑动、再以智术防堵的做法有关。","【王弼注择要】「多智巧诈，故难治也。」后文展开为「以智术动民」，继而「复以巧术防民之伪」，写出治理与民间巧伪互相滋长的过程。","【读法】这里不把难治简单归咎于人们受过教育。章中智的批评语境是巧诈与对抗性的施术；今日借用时，还要检视规则、激励和掌权者自己的做法。"]},{id:"two-political-directions",label:"以智治国，国之贼",showLabel:!0,sentences:[["故以",{text:"智",glossary:"zhi"},"治国，国之",{text:"贼",glossary:"zei"},"；不以",{text:"智",glossary:"zhi"},"治国，国之福。"]],note:["【白话】所以，以机巧权术治国，会成为国家的祸害；不依此种权术治国，才成为国家之福。两句对照的是治理所依的取向。","【王弼注择要】「思惟密巧，奸伪益滋。」注在此之前写民得知防堵之术而随之规避，说明施术与避术可能使巧伪越来越密。","【读法】贼在本句是损害国家之物，不只指盗贼身份。所据前注另有智犹治也等字面，本页不擅改字；解释主要据上下文明列的智术、巧诈链条。"]},{id:"recognizing-the-shared-pattern",label:"知此两者，亦稽式",showLabel:!0,sentences:[["知此两者，亦",{text:"稽式",glossary:"jishi"},"。常知",{text:"稽式",glossary:"jishi"},"，是谓",{text:"玄德",glossary:"xuande"},"。"]],note:["【白话】认识这两种治理取向，也就有了可参验的法式；常能明白并持守这种法式，称为玄德。此处法式重在辨明何种治理会反生巧伪。","【王弼注择要】「稽，同也。今古之所同，则不可废。」注以今古所同来解释稽，又说「能知稽式，是谓玄德」。","【读法】稽式常可按可考验的法式理解，本页再明确所据注的同义取径，不把考核与同两种训释无缝混成一条。常知也不是守住任何现成制度而永不修正。"]},{id:"depth-and-return-against-the-current",label:"与物反矣",showLabel:!0,sentences:[[{text:"玄德",glossary:"xuande"},"深矣，远矣，与物",{text:"反",glossary:"fan"},"矣，"]],note:["【白话】这种玄德幽深而影响长远，它与逐巧趋末的通常走向相反，使事物返归其真。此处先说与物相反，再依王注说明返真的方向。","【王弼注择要】与物反矣下注「反其真也」。注不只停在外表上与众不同，而是指出复其本真的方向。","【读法】反在句面有相反、相背之意，王注又接返真；不据此要求凡事故意逆行。玄德在本章另列守真、不以智术扰民的语境义。"]},{id:"arriving-at-great-concord",label:"然后乃至大顺",showLabel:!0,sentences:[["然后乃至",{text:"大顺",glossary:"dashun"},"。"]],note:["【白话】这样，才达到整体的顺适、和顺。末句把前面不以巧术相激、使物返真的方向，收束为大顺。","【读法】所据本句未见单独逐句王注，可承反其真也读。乃至表示经过前述过程才得以趋向，并非只要口称无智就会自然出现的结果。","【读法】现代相参时，大顺可帮助人反省关系是否更少欺诈、更多安定；不把它直接等同所有人服从同一个人，也不把古代使民之意改说成现代教育或治理的完整主张。"]}],s=[{id:"ming",term:"明",sense:3},{id:"yu",term:"愚",sense:1},{id:"zhi",term:"智",sense:2},{id:"zei",term:"贼",sense:1},{id:"jishi",term:"稽式",sense:1},{id:"xuande",term:"玄德",sense:2},{id:"fan",term:"反",sense:2},{id:"dashun",term:"大顺",sense:1}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十五章",tabindex:"-1"},[n("道德经第六十五章 "),a("a",{class:"header-anchor",href:"#道德经第六十五章","aria-label":'Permalink to "道德经第六十五章"'},"​")],-1)),r(o,{title:"怎样读明民与愚之，才不把古注和现代解释混在一起",summary:"本章以明民与愚之对举，再比较以智治国与不以智治国，最后落在稽式、玄德与大顺。王弼围绕巧诈蔽朴、守真顺自然，尤其批评先以智术动民、再以巧术防民的循环；其中仍有古代在上者使民的立场，需要如实呈现。",points:[{label:"先读",text:"明与愚先依本章所据注释义：多见巧诈蔽朴，与无知守真顺自然相对。"},{label:"再辨",text:"智多联系智术挑动与防堵的循环，不直接等同所有知识、教育或认识能力。"},{label:"后看",text:"稽式的王注强调今古所同，玄德与物反依反其真读，最后才到大顺。"}],hint:"愚读 yú，智读 zhì，稽式读 jī shì，贼读 zéi。玄德在本章连返真、大顺，不只沿用第十章生养不宰的解释。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"古之善为道者，非以明民，将以愚之。",tone:"先读特定字义",guide:"王注以巧诈蔽朴、守真自然解释，同时保留在上者使民的古代立场。"},{text:"故以智治国，国之贼；不以智治国，国之福。",tone:"识别施术与防堵的循环",guide:"智术挑动之后再以巧术压制，可能使规避与巧伪更密。"},{text:"玄德深矣，远矣，与物反矣，然后乃至大顺。",tone:"从相反到返真",guide:"依反其真也的注释，看清相反不是为了故意与人作对。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-明民与愚之可以直接译成启蒙与蒙昧吗" tabindex="-1">象：明民与愚之可以直接译成启蒙与蒙昧吗？ <a class="header-anchor" href="#象-明民与愚之可以直接译成启蒙与蒙昧吗" aria-label="Permalink to &quot;象：明民与愚之可以直接译成启蒙与蒙昧吗？&quot;">​</a></h3><p>这样的现代对照会遮住所据王注的特定含义。王弼把明连到多见巧诈蔽朴，把愚连到守真顺自然；同时，原文仍在提出治理者使民的方向，既不能忽略字义，也不能把古代权力立场删去。</p><h3 id="理-王弼怎样解释以智治国的反效" tabindex="-1">理：王弼怎样解释以智治国的反效？ <a class="header-anchor" href="#理-王弼怎样解释以智治国的反效" aria-label="Permalink to &quot;理：王弼怎样解释以智治国的反效？&quot;">​</a></h3><p>先用智术挑动人的趋逐，再用巧术防止由此生出的规避，人又识破并躲开这些术，于是更密的奸伪出现。注释所批评的是这样的相激循环，不能只概括为知识越多越坏。</p><h3 id="用-今天怎样借用返真而不替他人决定人生" tabindex="-1">用：今天怎样借用返真而不替他人决定人生？ <a class="header-anchor" href="#用-今天怎样借用返真而不替他人决定人生" aria-label="Permalink to &quot;用：今天怎样借用返真而不替他人决定人生？&quot;">​</a></h3><p>可以先减少自己制造的虚假激励、信息不明与反复控制，提供清楚规则和真实反馈。对方如何学习与成长，仍需保有参与、表达和选择的空间；这是现代应用的再判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先看自己是否参与制造了对抗。</strong> 当人们越来越擅长应付要求时，不只增加更隐蔽的防堵，也检查目标和奖惩是否正在奖励表面功夫。把问题放回互动过程，才更容易找到可调整的条件。</p><p><strong>让真实表达比猜测意图更容易。</strong> 清楚说明目的、条件和可变范围，减少暗示与试探。返真的现代启发，可以从这些可观察的安排开始，不必先给别人贴聪明或愚笨的标签。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否一面用某种激励挑动别人，一面又责怪他们学会规避？若减少巧术与猜测，我能先把哪些条件讲得更清楚？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 005a–005b 电子录文核对；末句大顺紧承与物反及王注反其真也。</li><li>明、愚依本章所据特定训释分义；智依多智巧诈、以智术动民与复以巧术防民之伪的上下文解释，不直接等同全部知识与学习。</li><li>所据以智治国前注另作智犹治也等字面，本页未擅改为其他字句，不用猜测的校改替代可追溯录文；古注择引限于可明确对应的语句。</li><li>稽式先释可参验的法式，再说明王注稽同也、今古之所同的解释；玄德与第十章生养不宰语境分义。</li><li>古代使民的治理立场与本站现代协作启发分层，既不删去其立场，也不把现代教育、参与和选择的判断冒作古注；尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，005a–005b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
